-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.priest.dps.Name"] = "Damage"
L["rm.era.priest.dps.Description"] = "Damage from level 1 to 60, and the Priest default whenever the healer premade does not apply (solo, Shadow, or no talents yet). Shadowform when learned; before a pull a shield when solo, then Holy Fire (without Shadowform), Mind Blast or Smite. Shadow Word: Pain once per target that will live, Mind Blast on cooldown, Mind Flay as the filler (Smite and Holy Nova before you have it), and the wand on a dying target or when your mana runs low while solo. Vampiric Embrace and Devouring Plague on long fights, never in raids. Reminders: Inner Fire, Fortitude, racial buffs, Inner Focus with Mind Blast, Psychic Scream when two enemies reach you at half health, Fade when your target turns on you, Desperate Prayer. Target choice, multi-dotting and downranking stay with you."
L["rm.era.priest.dps.simulator.Name"] = "Damage (simulator Undead raid)"
L["rm.era.priest.dps.simulator.Description"] = "The recommended damage priority with simulator' raid choice for Undead priests: Inner Focus is spent on Devouring Plague instead of Mind Blast, and Devouring Plague is cast in raids too, so use it only where your raid has debuff slots to spare. No Vampiric Embrace. An alternative to the recommended damage premade, off by default: enable it and disable that one, or raise its priority."
L["rm.era.priest.dps.warcrafttavern.Name"] = "Damage (Warcraft Tavern wand economy)"
L["rm.era.priest.dps.warcrafttavern.Description"] = "Warcraft Tavern's low-downtime leveling style, an alternative to the recommended damage premade, off by default: enable it and disable that one, or raise its priority. Solo: Mind Blast to pull, Shadow Word: Pain once, Mind Blast again only while the target is above 30%, and your wand between Mind Blasts instead of Smite or Mind Flay. No automatic shield before pulls. In a group: Shadow Word: Pain, Mind Blast, Mind Flay. Same reminders as the recommended premade."
L["rm.era.priest.healer.Name"] = "Healer"
L["rm.era.priest.healer.Description"] = "Chosen in a group when Holy or Discipline is your main talent tree. Heals the friendly unit you target: Power Word: Shield below 30%, Flash Heal below 40%, dispels, Prayer of Healing when three of your party are hurt, Greater Heal (Heal or Lesser Heal before you learn it) below half health, Renew while moving or on light damage, then Heal rank 3 as the efficient top-up. Out of combat it offers Fortitude on your target. Targeting an enemy gives Shadow Word: Pain and Smite. Reminders: Inner Fire, Fortitude, Divine Spirit, Inner Focus, Desperate Prayer; Power Infusion is off by default. Choosing whom to heal and downranking stay with you."
L["rm.forever.priest.dps.Name"] = "Shadow and solo damage"
L["rm.forever.priest.dps.Description"] = "Shadow, and every Priest's solo play, from level 1 to 60; the Forever Priest default. Pulls with Power Word: Shield (solo) and Mind Blast (Holy Fire for Holy and Discipline, Smite before Mind Blast). Then Shadowform once learned, your own Shadow Word: Pain and Devouring Plague, Mind Blast, Holy Fire into Penance for Discipline, Mind Flay in Shadowform; solo before Shadowform, Holy Nova on three enemies with Holy Purpose, then the wand (Smite without one). Moving: Pain, Plague. Reminders: Inner Fire, Fortitude, Divine Spirit, racial buffs, Vampiric Embrace, Inner Focus, Silence, Elune's Light; Psychic Scream is off by default. Health and mana are hidden from addons on Forever, so executing with Shadow Word: Death, healing yourself and Dark Sacrifice are your call. Built from level-30 beta guides; Shadowform play follows Mobalytics."
L["rm.forever.priest.dps.mobalytics.Name"] = "DoT and wand leveling (Mobalytics)"
L["rm.forever.priest.dps.mobalytics.Description"] = "Mobalytics' leveling style, an alternative to the recommended Shadow premade, off by default: enable it and disable that one, or raise its priority. Mind Blast and Holy Fire only on tough mobs (elites, or two levels above you), your own Shadow Word: Pain and Devouring Plague, then the wand (Smite without one). From Shadowform: Mind Blast, Pain, Plague, Mind Flay. Shield and Renew on yourself between pulls, Cure Disease on yourself. Health and mana are hidden from addons on Forever, so healing yourself is your call. Spreading Pain across several mobs is up to you."
L["rm.forever.priest.healer.Name"] = "Discipline and Holy healing"
L["rm.forever.priest.healer.Description"] = "Group healing once Discipline or Holy is your main talent tree and you do not know Shadowform. Heals your current friendly target: before the pull Power Word: Shield, Prayer of Mending and Renew; Dispel Magic and Abolish or Cure Disease; Prayer of Mending; Holy Nova on Holy Purpose; Penance; Renew when missing; Heal (Lesser Heal before it). On an enemy: Shadow Word: Pain, Holy Fire, Penance, Smite, wand. Reminders: Inner Fire, Fortitude, Divine Spirit, Power Infusion on another player, Inner Focus in combat and the racial spells. Health and mana are hidden from addons on Forever, so the target you pick is the only sign of who needs healing; emergency heals, Prayer of Healing, Binding Heal, Greater and Flash Heal, Desperate Prayer and Dark Sacrifice are your call. You pick who to heal and the rank; a Discipline healer before Penance (20–29) selects it by hand."
L["rm.mop.priest.discipline.Name"] = "Recommended"
L["rm.mop.priest.discipline.Description"] = "Discipline healing from level 10 to 90, chosen in the Discipline specialization. Target a friend to heal them: Power Word: Shield when they are low, before the pull and about every 12 seconds for Rapture; Flash Heal on Surge of Light; Penance; Flash Heal when they are very low; Binding Heal when you are both hurt; Prayer of Mending; Prayer of Healing and your tier-6 talent when three allies are hurt; Greater Heal; Renew while moving; Heal to top up. Under Spirit Shell it suggests Prayer of Healing or Greater Heal. Target an enemy to heal through Atonement: Penance, Power Word: Solace or Holy Fire, your tier-6 talent on packs, Shadow Word: Pain when solo, Smite. Reminders: Inner Fire, Fortitude, Archangel at five Evangelism, Inner Focus, Pain Suppression on a dying target, Shadowfiend or Mindbender for mana, Power Infusion, Desperate Prayer. Left to you: whom to heal, Spirit Shell timing (a reminder you can switch on), Power Word: Barrier, Void Shift and Grace stacks on the tank."
L["rm.mop.priest.holy.Name"] = "Recommended"
L["rm.mop.priest.holy.Description"] = "Holy healing from level 10 to 90, chosen in the Holy specialization. Target a friend to heal them: Holy Word: Serenity in Chakra: Serenity; Power Word: Shield only when they are about to die; Flash Heal on Surge of Light; Prayer of Mending; Flash Heal when very low; Binding Heal when you are both hurt; in a group with three allies hurt, Circle of Healing, Holy Word: Sanctuary in Chakra: Sanctuary, your tier-6 talent and Prayer of Healing; Renew; Greater Heal when low or at two Serendipity; Heal. Target an enemy to deal damage: Holy Word: Chastise, Power Word: Solace or Holy Fire, Shadow Word: Pain when solo, your tier-6 talent on packs, Smite. An empty chakra is filled for you (Sanctuary in a raid, Serenity in a party, Chastise solo) and never swapped. Reminders: Inner Fire, Fortitude, Guardian Spirit on a dying target, Divine Hymn when five allies are badly hurt, Shadowfiend or Mindbender for mana, Power Infusion, Desperate Prayer. Left to you: whom to heal, placing Holy Word: Sanctuary, Lightwell and Void Shift."
L["rm.mop.priest.holy.icyveins.Name"] = "Emergency heals last (Icy Veins)"
L["rm.mop.priest.holy.icyveins.Description"] = "Off by default. Icy Veins' Holy order, picked by your chakra. In Chakra: Sanctuary: Holy Word: Sanctuary when three allies are hurt, Renew, Circle of Healing, Prayer of Mending, Prayer of Healing, then Binding Heal and Flash Heal only in emergencies. Otherwise: Renew, Holy Word: Serenity, Prayer of Mending, Greater Heal, Heal, Binding Heal, Flash Heal, Power Word: Shield last, and Flash Heal as the filler before you learn Heal. Same switch, reminders and damage list as the recommended Holy premade; enable it and disable that one to use it."
L["rm.mop.priest.shadow.Name"] = "Recommended"
L["rm.mop.priest.shadow.Description"] = "Shadow damage from level 10 to 90, chosen in the Shadow specialization. Opens with Mind Spike, Mind Blast or your DoTs. Devouring Plague at three Shadow Orbs (when Mind Blast is ready or still six seconds away), Mind Blast, Shadow Word: Death below 20% health, Mind Flay while your Devouring Plague is up if you took Solace and Insanity, Shadow Word: Pain and Vampiric Touch refreshed near the end on a target that will live, Mind Spike on Surge of Darkness, Halo, Cascade or Divine Star at their best range, then Mind Flay. A Mind Flay is cut short for Mind Blast or Shadow Word: Death, or after its second tick; other channels are never interrupted. While moving it suggests instants only. On five or more enemies: your tier-6 talent, DoTs on your target and Mind Sear. Reminders: Shadowform, Inner Fire, Fortitude, Silence on interruptible casts, Shadowfiend or Mindbender and Power Infusion on long fights, Vampiric Embrace, Desperate Prayer and Dispersion when low. Left to you: DoTs on other targets and where Mind Sear lands."
L["rm.mop.priest.shadow.warcrafttavern.Name"] = "No Insanity priority (Warcraft Tavern)"
L["rm.mop.priest.shadow.warcrafttavern.Description"] = "Off by default. Warcraft Tavern's Shadow order: Devouring Plague at three Shadow Orbs, Shadow Word: Death below 20%, Mind Blast, Vampiric Touch, Shadow Word: Pain, Mind Spike on Surge of Darkness, your tier-6 talent, Mind Flay. Unlike the recommended Shadow premade it never raises Mind Flay under Devouring Plague and does not hold Devouring Plague for Mind Blast. Same opener, movement, pack and reminder steps; enable it and disable the recommended one to use it."
L["rm.mop.priest.unspecialized.Name"] = "Unspecialized"
L["rm.mop.priest.unspecialized.Description"] = "For levels 1 to 9, or any priest who has not chosen a specialization yet. On an enemy: Shadow Word: Pain when it will live long enough, then Smite. On a friend: Flash Heal when they are low, otherwise Power Word: Shield. Reminders: Inner Fire, and a shield on yourself when you are solo and hurt. Choosing a specialization at 10 switches to its own premade."
L["rm.retail.priest.discipline.Name"] = "Atonement (Icy Veins)"
L["rm.retail.priest.discipline.Description"] = "Discipline in Midnight, for reference: Blizzard's Assisted Combat does not cover healers, the game hides everyone's health in combat and Rotation Master picks a spell, not a target, so this runs the damage that heals through Atonement and leaves deciding who to heal to you. On a friendly target: Power Word: Shield (Void Shield), Penance, Flash Heal. On an enemy: Shadow Word: Pain when you have not cast it for 12 seconds, Mind Blast, Penance, Shield, Shadow Word: Death, Void Blast, Smite. Reminders in combat: Power Word: Radiance, Evangelism, Ultimate Penitence, Pain Suppression on a friendly target; Fortitude between pulls. Desperate Prayer is your call. Raid ramps before big damage are yours to time."
L["rm.retail.priest.discipline.wowhead.Name"] = "Death first reference (Wowhead)"
L["rm.retail.priest.discipline.wowhead.Description"] = "Reference only, off by default: Wowhead's Season 1 Oracle order, which keeps Shadow Word: Pain up by reading the debuff that Midnight hides in combat. Shadow Word: Pain, Shadow Word: Death on cooldown, Penance, Mind Blast, Smite; Penance first on a friendly target. Same reminders as the Icy Veins premade."
L["rm.retail.priest.holy.Name"] = "Icy Veins"
L["rm.retail.priest.holy.Description"] = "Holy in Midnight, for reference: the game hides everyone's health in combat and Rotation Master picks a spell, not a target, so this keeps your Holy Words, Prayer of Mending and procs moving on whatever you target and leaves triage to you. On a friendly target: Holy Word: Sanctify, Holy Word: Serenity, Prayer of Mending, Prayer of Healing with Surge of Light, Benediction, Prayer of Healing with Lightweaver, Flash Heal with Surge of Light, Prayer of Healing in a group, Holy Nova while moving, Flash Heal. On an enemy: Holy Word: Chastise, Holy Fire, Holy Nova while moving, Smite. Reminders: Apotheosis, Divine Hymn and Halo in combat, Guardian Spirit on a friendly target (health is hidden on Retail, so whether it is about to die is your call), Fortitude. Desperate Prayer is yours."
L["rm.retail.priest.initial.Name"] = "Blizzard Assisted"
L["rm.retail.priest.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Priest's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Priest premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.priest.shadow.Name"] = "Blizzard Assisted"
L["rm.retail.priest.shadow.Description"] = "Recommended for Shadow in Midnight. In combat the game now hides your DoTs, buffs, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat suggestion (the one-button rotation, which keeps your DoTs, Shadowform and Voidform going and lets Mind Flay finish), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: Power Infusion in the 20 seconds after you cast Voidform, Shadowform and Power Word: Fortitude between pulls, Silence on an interruptible cast (it lights only where the game lets the cast be read). Health is hidden on Retail, so Desperate Prayer is your call."
L["rm.retail.priest.shadow.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.priest.shadow.icyveins.Description"] = "Reference only, off by default: the Icy Veins and SimulationCraft order reads DoT timers, Madness and Voidform, which Midnight hides in combat; Insanity and health are hidden on Retail, so the Insanity-cap Madness, the Shadow Word: Death execute and Desperate Prayer are left to you. Vampiric Touch before the pull; Tentacle Slam to apply Vampiric Touch; Vampiric Touch and Shadow Word: Pain refreshed in their last 30%; Shadow Word: Madness when it is ending or in Voidform; Void Blast during Madness; Tentacle Slam at two charges; Void Torrent; Mind Blast; Tentacle Slam; Mind Flay: Insanity during Madness; Void Volley; Death and Pain while moving; Mind Flay, clipped for a ready Mind Blast. Reminders: Halo, Voidform with both DoTs up, Power Infusion in Voidform."
L["rm.sod.priest.dps.Name"] = "Damage (SoD)"
L["rm.sod.priest.dps.Description"] = "Damage on Season of Discovery realms, from level 1 to 60, using the runes you have engraved. Shadowform; Vampiric Touch or Mind Blast to pull (Penance, Holy Fire or Smite before Shadowform). Void Plague, Shadow Word: Pain and Vampiric Touch kept up (refreshed near the end only without Pain and Suffering engraved), Mind Blast on cooldown, Mind Flay on Melting Faces, Shadow Word: Death while you are above half health, then Mind Spike as the filler, or Mind Flay with the Phase 8 six-piece set. Void Zone and Mind Sear on four or more enemies. The wand on a dying solo target. Reminders: Inner Fire, Fortitude, Homunculi, Shadowfiend, Eye of the Void and Dispersion, Inner Focus, Psychic Scream, Fade, Desperate Prayer."
L["rm.sod.priest.dps.wowhead.Name"] = "Damage (SoD, Wowhead Mind Spike stacks)"
L["rm.sod.priest.dps.wowhead.Description"] = "The Wowhead and Warcraft Tavern way for Season of Discovery, an alternative to the recommended Season of Discovery damage premade, off by default: enable it and disable that one, or raise its priority. Mind Blast waits for three of your Mind Spike stacks on the target (it is cast normally until you engrave Mind Spike), Mind Flay only on Melting Faces, Mind Spike as the filler. Everything else matches the recommended premade."
L["rm.sod.priest.healer.Name"] = "Healer (SoD)"
L["rm.sod.priest.healer.Description"] = "Chosen on Season of Discovery realms in a group when Holy or Discipline is your main talent tree; follows Icy Veins. Heals the friendly unit you target: Prayer of Mending before the pull and whenever ready, Shield below half health, Penance, instant Flash Heal on Surge of Light, emergency Flash Heal, dispels, Circle of Healing and Prayer of Healing when three of your party are hurt, Greater Heal below half health, Renew while moving or on light damage, then Heal. Targeting an enemy gives Pain, Void Plague, Penance, Holy Fire and Smite. Reminders include Shadowfiend, Pain Suppression on a dying target, Power Word: Barrier and Spirit of the Redeemer when the party is hurt."
L["rm.sod.priest.healer.warcrafttavern.Name"] = "Healer (SoD, Warcraft Tavern)"
L["rm.sod.priest.healer.warcrafttavern.Description"] = "Warcraft Tavern's Serendipity loop, built for Serendipity and Soul Warding, an alternative to the recommended Season of Discovery healer premade, off by default: enable it and disable that one, or raise its priority. Prayer of Mending on cooldown, Shield on your target whenever it can take one (with Soul Warding engraved; else below half health), Penance on heavy damage, Circle of Healing for three hurt, Greater Heal or Prayer of Healing at three Serendipity stacks, Renew on minor damage, and Flash Heal on minor injuries to build the stacks (with Serendipity engraved; else below 30%)."
L["rm.tbc.priest.dps.icyveins.Name"] = "Damage (Icy Veins)"
L["rm.tbc.priest.dps.icyveins.Description"] = "Damage from level 1 to 70, used whenever the healer premade does not apply. Smite and wand early, then Mind Blast, Shadow Word: Pain, Mind Flay, Shadowform, Vampiric Touch and Shadow Word: Death as you learn them; DoTs before Mind Blast; a dying target is wanded when solo. Holy and Discipline questers get Holy Fire and Smite. Reminders: Inner Fire, Fortitude, racial buffs, Inner Focus, Shadowfiend. A Mind Flay past its first tick is cut short for a ready Mind Blast, or Shadow Word: Death above half health. Shields and healing stay with you."
L["rm.tbc.priest.dps.wowhead.Name"] = "Damage (Wowhead)"
L["rm.tbc.priest.dps.wowhead.Description"] = "Damage after Wowhead's guides, an alternative to the recommended Icy Veins damage premade, off by default: enable it and disable that one, or raise its priority. Mind Blast opens and goes before DoT refreshes, Vampiric Embrace only when your health drops, and a dying target gets spells instead of the wand. Otherwise the same as the recommended premade."
L["rm.tbc.priest.healer.icyveins.Name"] = "Healer (Icy Veins)"
L["rm.tbc.priest.healer.icyveins.Description"] = "Healing after Icy Veins' order: Shield, dispels, Binding Heal, Renew, Flash Heal, Greater Heal (any rank), group heals, and Prayer of Mending last. You choose whom to heal. An alternative to the recommended Wowhead healer premade, off by default: enable it and disable that one, or raise its priority."
L["rm.tbc.priest.healer.wowhead.Name"] = "Healer (Wowhead)"
L["rm.tbc.priest.healer.wowhead.Description"] = "Healing in a group when Holy or Discipline is your main talent tree. It advises on the friendly unit you target; you choose whom to heal. Prayer of Mending before pulls and whenever ready, Renew, Power Word: Shield in emergencies, dispels, Circle of Healing or Prayer of Healing for group damage, Binding, Flash and Greater Heal, and Greater Heal rank 1 as a cheap top-up. With an enemy targeted it offers light damage."
